import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Button,
  Container,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Chip,
  IconButton,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Badge,
  TextField,
  InputAdornment,
  Alert,
  CircularProgress,
} from "@mui/material";

import {
  Menu as MenuIcon,
  Restaurant,
  ShoppingCart,
  ReceiptLong,
  RateReview,
  Person,
  Logout,
  Search,
  Add,
  Remove,
  Home,
} from "@mui/icons-material";

const menuItems = [
  {
    name: "Masala Dosa",
    price: 80,
    category: "Breakfast",
    image:
      "https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=600",
    description: "Crispy dosa served with potato masala, chutney and sambar.",
  },
  {
    name: "Biryani",
    price: 180,
    category: "Lunch",
    image:
      "https://www.awesomecuisine.com/wp-content/uploads/2008/03/Vegetable-Biryani.jpg",
    description: "Flavorful aromatic biryani served hot.",
  },
  {
    name: "Butter Chicken",
    price: 220,
    category: "Lunch",
    image:
      "https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?w=600",
    description: "Creamy butter chicken with rich Indian spices.",
  },
  {
    name: "Paneer Tikka",
    price: 160,
    category: "Snacks",
    image:
      "https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=600",
    description: "Grilled paneer with vegetables and spices.",
  },
  {
    name: "Samosa",
    price: 40,
    category: "Snacks",
    image:
      "https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600",
    description: "Crispy samosa with spicy potato filling.",
  },
  {
    name: "Chai",
    price: 20,
    category: "Beverages",
    image:
      "https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=600",
    description: "Freshly prepared Indian tea.",
  },
  {
    name: "Gulab Jamun",
    price: 50,
    category: "Dessert",
    image:
      "https://images.unsplash.com/photo-1666190094762-9c1b2d5b4b9e?w=600",
    description: "Soft gulab jamun served warm.",
  },
];

const categories = [
  "All",
  "Breakfast",
  "Lunch",
  "Snacks",
  "Beverages",
  "Dessert",
];

const UserDashboard = ({ user, onLogout }) => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activePage, setActivePage] = useState("home");

  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");

  const [cart, setCart] = useState([]);

  const [orders, setOrders] = useState([]);
  const [loadingOrders, setLoadingOrders] = useState(false);

  const [orderMessage, setOrderMessage] = useState("");
  const [error, setError] = useState("");

  const loadOrders = async () => {
    try {
      setLoadingOrders(true);
      setError("");

      const response = await axios.get("/api/tokens");

      const allOrders = Array.isArray(response.data)
        ? response.data
        : [];

      const myOrders = allOrders.filter(
        (order) =>
          order.customerName?.toLowerCase() ===
          user.name?.toLowerCase()
      );

      setOrders(myOrders);
    } catch (err) {
      console.error("Error loading orders:", err);

      setError(
        err.response?.data?.message ||
        "Unable to load your orders."
      );
    } finally {
      setLoadingOrders(false);
    }
  };

  useEffect(() => {
    loadOrders();
  }, []);

  const filteredMenu = useMemo(() => {
    return menuItems.filter((item) => {
      const matchesSearch = item.name
        .toLowerCase()
        .includes(search.toLowerCase());

      const matchesCategory =
        category === "All" || item.category === category;

      return matchesSearch && matchesCategory;
    });
  }, [search, category]);

  const addToCart = (item) => {
    setCart((previousCart) => {
      const existing = previousCart.find(
        (cartItem) => cartItem.name === item.name
      );

      if (existing) {
        return previousCart.map((cartItem) =>
          cartItem.name === item.name
            ? {
              ...cartItem,
              quantity: cartItem.quantity + 1,
            }
            : cartItem
        );
      }

      return [
        ...previousCart,
        {
          ...item,
          quantity: 1,
        },
      ];
    });
  };

  const increaseQuantity = (name) => {
    setCart((previousCart) =>
      previousCart.map((item) =>
        item.name === name
          ? {
            ...item,
            quantity: item.quantity + 1,
          }
          : item
      )
    );
  };

  const decreaseQuantity = (name) => {
    setCart((previousCart) =>
      previousCart
        .map((item) =>
          item.name === name
            ? {
              ...item,
              quantity: item.quantity - 1,
            }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) =>
      total + item.price * item.quantity,
    0
  );

  const placeOrder = async () => {
    if (cart.length === 0) {
      setError("Your cart is empty.");
      return;
    }

    try {
      setError("");
      setOrderMessage("");

      for (const item of cart) {
        await axios.post("/api/tokens", {
          itemName: item.name,
          category: item.category,
          price: item.price,
          quantity: item.quantity,
          status: "Pending",
          customerName: user.name,
          specialInstructions: "",
          preparationTime: 15,
          image: item.image,
        });
      }

      setCart([]);

      setOrderMessage(
        "Order placed successfully!"
      );

      await loadOrders();

      setActivePage("orders");
    } catch (err) {
      console.error("Order error:", err);

      setError(
        err.response?.data?.message ||
        "Unable to place order."
      );
    }
  };

  const handleLogout = () => {
    onLogout();
  };

  const renderHome = () => (
    <>
      <Box
        sx={{
          mb: 4,
          p: 4,
          borderRadius: 4,
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
          color: "white",
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
            mb: 1,
          }}
        >
          Welcome, {user.name}
        </Typography>

        <Typography variant="h6">
          What would you like to eat today?
        </Typography>
      </Box>

      <Typography
        variant="h5"
        sx={{
          fontWeight: 800,
          mb: 2,
          color: "#2E7D32",
        }}
      >
        Popular Menu
      </Typography>

      <Grid container spacing={3}>
        {menuItems.slice(0, 4).map((item) => (
          <Grid item xs={12} sm={6} md={3} key={item.name}>
            <Card
              sx={{
                height: "100%",
                borderRadius: 3,
                overflow: "hidden",
                boxShadow:
                  "0 4px 15px rgba(0,0,0,0.08)",
              }}
            >
              <CardMedia
                component="img"
                height="180"
                image={item.image}
                alt={item.name}
              />

              <CardContent>
                <Typography
                  variant="h6"
                  sx={{ fontWeight: 700 }}
                >
                  {item.name}
                </Typography>

                <Typography
                  color="text.secondary"
                  sx={{ mb: 2 }}
                >
                  ₹{item.price}
                </Typography>

                <Button
                  fullWidth
                  variant="contained"
                  startIcon={<Add />}
                  onClick={() => addToCart(item)}
                  sx={{
                    background:
                      "linear-gradient(135deg, #2E7D32, #4CAF50)",
                  }}
                >
                  Add to Cart
                </Button>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </>
  );

  const renderMenu = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Food Menu
      </Typography>

      <TextField
        fullWidth
        placeholder="Search food..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        sx={{ mb: 2 }}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <Search />
            </InputAdornment>
          ),
        }}
      />

      <Box
        sx={{
          display: "flex",
          gap: 1,
          flexWrap: "wrap",
          mb: 4,
        }}
      >
        {categories.map((item) => (
          <Button
            key={item}
            variant={
              category === item
                ? "contained"
                : "outlined"
            }
            onClick={() => setCategory(item)}
            sx={{
              borderRadius: 5,
              color:
                category === item
                  ? "white"
                  : "#2E7D32",
              borderColor: "#2E7D32",
              backgroundColor:
                category === item
                  ? "#2E7D32"
                  : "transparent",
            }}
          >
            {item}
          </Button>
        ))}
      </Box>

      <Grid container spacing={3}>
        {filteredMenu.map((item) => (
          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={item.name}
          >
            <Card
              sx={{
                height: "100%",
                borderRadius: 3,
                overflow: "hidden",
              }}
            >
              <CardMedia
                component="img"
                height="210"
                image={item.image}
                alt={item.name}
              />

              <CardContent>
                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    mb: 1,
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 700 }}
                  >
                    {item.name}
                  </Typography>

                  <Chip
                    label={item.category}
                    size="small"
                    color="success"
                  />
                </Box>

                <Typography
                  color="text.secondary"
                  sx={{ mb: 2 }}
                >
                  {item.description}
                </Typography>

                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 800,
                      color: "#2E7D32",
                    }}
                  >
                    ₹{item.price}
                  </Typography>

                  <Button
                    variant="contained"
                    startIcon={<Add />}
                    onClick={() => addToCart(item)}
                    sx={{
                      backgroundColor: "#2E7D32",
                    }}
                  >
                    Add
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </>
  );

  const renderCart = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Cart
      </Typography>

      {cart.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <ShoppingCart
            sx={{
              fontSize: 60,
              color: "#2E7D32",
              mb: 2,
            }}
          />

          <Typography variant="h6">
            Your cart is empty
          </Typography>

          <Button
            variant="contained"
            sx={{ mt: 2 }}
            onClick={() => setActivePage("menu")}
          >
            Browse Menu
          </Button>
        </Card>
      ) : (
        <>
          {cart.map((item) => (
            <Card
              key={item.name}
              sx={{
                mb: 2,
                borderRadius: 3,
              }}
            >
              <CardContent>
                <Grid
                  container
                  alignItems="center"
                  spacing={2}
                >
                  <Grid item xs={12} sm={5}>
                    <Typography
                      variant="h6"
                      sx={{ fontWeight: 700 }}
                    >
                      {item.name}
                    </Typography>

                    <Typography color="text.secondary">
                      ₹{item.price} each
                    </Typography>
                  </Grid>

                  <Grid item xs={12} sm={4}>
                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 1,
                      }}
                    >
                      <IconButton
                        onClick={() =>
                          decreaseQuantity(item.name)
                        }
                      >
                        <Remove />
                      </IconButton>

                      <Typography
                        sx={{
                          fontWeight: 700,
                          minWidth: 30,
                          textAlign: "center",
                        }}
                      >
                        {item.quantity}
                      </Typography>

                      <IconButton
                        onClick={() =>
                          increaseQuantity(item.name)
                        }
                      >
                        <Add />
                      </IconButton>
                    </Box>
                  </Grid>

                  <Grid item xs={12} sm={3}>
                    <Typography
                      variant="h6"
                      sx={{
                        fontWeight: 800,
                        color: "#2E7D32",
                      }}
                    >
                      ₹{item.price * item.quantity}
                    </Typography>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          ))}

          <Card sx={{ p: 3, mt: 3 }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                mb: 2,
              }}
            >
              <Typography variant="h6">
                Total
              </Typography>

              <Typography
                variant="h5"
                sx={{
                  fontWeight: 800,
                  color: "#2E7D32",
                }}
              >
                ₹{cartTotal}
              </Typography>
            </Box>

            <Button
              fullWidth
              variant="contained"
              size="large"
              onClick={placeOrder}
              sx={{
                background:
                  "linear-gradient(135deg, #2E7D32, #4CAF50)",
              }}
            >
              PLACE ORDER
            </Button>
          </Card>
        </>
      )}
    </>
  );

  const renderOrders = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Orders
      </Typography>

      {loadingOrders ? (
        <Box sx={{ textAlign: "center", py: 5 }}>
          <CircularProgress />
        </Box>
      ) : orders.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <ReceiptLong
            sx={{
              fontSize: 60,
              color: "#2E7D32",
            }}
          />

          <Typography variant="h6" sx={{ mt: 2 }}>
            No orders yet
          </Typography>

          <Button
            variant="contained"
            sx={{ mt: 2 }}
            onClick={() => setActivePage("menu")}
          >
            Order Food
          </Button>
        </Card>
      ) : (
        orders.map((order) => (
          <Card
            key={order._id}
            sx={{
              mb: 2,
              borderRadius: 3,
            }}
          >
            <CardContent>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  flexWrap: "wrap",
                  gap: 2,
                }}
              >
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 800 }}
                  >
                    {order.itemName}
                  </Typography>

                  <Typography color="text.secondary">
                    Quantity: {order.quantity}
                  </Typography>

                  <Typography color="text.secondary">
                    ₹{order.price * order.quantity}
                  </Typography>
                </Box>

                <Chip
                  label={order.status}
                  color={
                    order.status === "Served"
                      ? "success"
                      : order.status === "Preparing"
                        ? "warning"
                        : "info"
                  }
                />
              </Box>
            </CardContent>
          </Card>
        ))
      )}
    </>
  );

  const renderReviews = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Reviews
      </Typography>

      <Card sx={{ p: 4 }}>
        <RateReview
          sx={{
            fontSize: 60,
            color: "#2E7D32",
            mb: 2,
          }}
        />

        <Typography variant="h6">
          Ratings & Reviews
        </Typography>

        <Typography
          color="text.secondary"
          sx={{ mt: 1 }}
        >
          Review functionality will be connected after
          the order workflow is completed.
        </Typography>
      </Card>
    </>
  );

  const renderProfile = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Profile
      </Typography>

      <Card sx={{ p: 4 }}>
        <Person
          sx={{
            fontSize: 60,
            color: "#2E7D32",
          }}
        />

        <Typography variant="h5" sx={{ mt: 2 }}>
          {user.name}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Mobile: {user.mobile}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Account Type: User
        </Typography>
      </Card>
    </>
  );

  const renderPage = () => {
    if (activePage === "home") return renderHome();
    if (activePage === "menu") return renderMenu();
    if (activePage === "cart") return renderCart();
    if (activePage === "orders") return renderOrders();
    if (activePage === "reviews") return renderReviews();
    if (activePage === "profile") return renderProfile();

    return renderHome();
  };

  const navigate = (page) => {
    setActivePage(page);
    setDrawerOpen(false);
    setOrderMessage("");
    setError("");
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        backgroundColor: "#f5f7f5",
      }}
    >
      <AppBar
        position="sticky"
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            onClick={() => setDrawerOpen(true)}
          >
            <MenuIcon />
          </IconButton>

          <Restaurant sx={{ mx: 1 }} />

          <Typography
            variant="h5"
            sx={{
              fontWeight: 800,
              flexGrow: 1,
            }}
          >
            CanteenPro
          </Typography>

          <Typography
            sx={{
              mr: 2,
              display: { xs: "none", sm: "block" },
            }}
          >
            Hi, {user.name}
          </Typography>

          <IconButton
            color="inherit"
            onClick={() => navigate("cart")}
          >
            <Badge
              badgeContent={cartCount}
              color="error"
            >
              <ShoppingCart />
            </Badge>
          </IconButton>
        </Toolbar>
      </AppBar>

      <Drawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
      >
        <Box sx={{ width: 280 }}>
          <Box
            sx={{
              p: 3,
              background:
                "linear-gradient(135deg, #2E7D32, #4CAF50)",
              color: "white",
            }}
          >
            <Typography
              variant="h5"
              sx={{ fontWeight: 800 }}
            >
              CanteenPro
            </Typography>

            <Typography>
              User Panel
            </Typography>
          </Box>

          <List>
            <ListItemButton
              onClick={() => navigate("home")}
            >
              <ListItemIcon>
                <Home />
              </ListItemIcon>
              <ListItemText primary="Home" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("menu")}
            >
              <ListItemIcon>
                <Restaurant />
              </ListItemIcon>
              <ListItemText primary="Menu" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("cart")}
            >
              <ListItemIcon>
                <ShoppingCart />
              </ListItemIcon>
              <ListItemText primary="Cart" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("orders")}
            >
              <ListItemIcon>
                <ReceiptLong />
              </ListItemIcon>
              <ListItemText primary="My Orders" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("reviews")}
            >
              <ListItemIcon>
                <RateReview />
              </ListItemIcon>
              <ListItemText primary="Reviews" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("profile")}
            >
              <ListItemIcon>
                <Person />
              </ListItemIcon>
              <ListItemText primary="Profile" />
            </ListItemButton>

            <Divider />

            <ListItemButton onClick={handleLogout}>
              <ListItemIcon>
                <Logout color="error" />
              </ListItemIcon>

              <ListItemText
                primary="Logout"
                sx={{ color: "error.main" }}
              />
            </ListItemButton>
          </List>
        </Box>
      </Drawer>

      <Container
        maxWidth="xl"
        sx={{
          py: 4,
        }}
      >
        {orderMessage && (
          <Alert
            severity="success"
            sx={{ mb: 3 }}
          >
            {orderMessage}
          </Alert>
        )}

        {error && (
          <Alert
            severity="error"
            sx={{ mb: 3 }}
          >
            {error}
          </Alert>
        )}

        {renderPage()}
      </Container>
    </Box>
  );
};

export default UserDashboard;
